import SwiftUI
import Photos
import Auth

struct ContentView: View {
    @ObservedObject var auth: AuthStore
    @ObservedObject var language: LanguageStore

    var body: some View {
        Group {
            if auth.isLoading {
                ProgressView()
            } else if auth.isAuthenticated {
                MainAppView(auth: auth, language: language)
            } else {
                SignInView(auth: auth, language: language)
            }
        }
    }
}

private struct SignInView: View {
    @ObservedObject var auth: AuthStore; @ObservedObject var language: LanguageStore
    @State private var email=""; @State private var password=""; @State private var signingIn=false
    private func authError(_ key:String)->String{switch key{case "auth_invalid_credentials":return language.text("Incorrect email or password.","E-mail ou mot de passe incorrect.");case "auth_email_not_confirmed":return language.text("Please confirm your email before signing in.","Veuillez confirmer votre e-mail avant de vous connecter.");case "auth_user_already_registered":return language.text("An account already exists with this email.","Un compte existe déjà avec cet e-mail.");case "auth_password_too_short":return language.text("Your password must contain at least 8 characters.","Votre mot de passe doit contenir au moins 8 caractères.");case "auth_invalid_email":return language.text("Enter a valid email address.","Saisissez une adresse e-mail valide.");case "auth_network_error":return language.text("Unable to connect. Check your internet connection and try again.","Connexion impossible. Vérifiez votre connexion Internet et réessayez.");case "auth_too_many_requests":return language.text("Too many attempts. Please wait a moment and try again.","Trop de tentatives. Patientez un instant puis réessayez.");default:return language.text("Something went wrong. Please try again.","Une erreur est survenue. Veuillez réessayer.")}}
    var body: some View { NavigationStack { VStack(spacing:22) { HStack{Spacer();Menu(language.language.title){ForEach(LanguageStore.Language.allCases){item in Button(item.title){language.language=item}}}.buttonStyle(.bordered)};Spacer();Text("Libérons").font(.system(size:44,weight:.bold,design:.rounded));Text(language.text("Keep your memories. Free your space.","Gardez vos souvenirs. Libérez votre espace.")).foregroundStyle(.secondary).multilineTextAlignment(.center);TextField(language.text("Email","E-mail"),text:$email).textInputAutocapitalization(.never).autocorrectionDisabled().keyboardType(.emailAddress).textContentType(.emailAddress).padding().background(.secondary.opacity(0.10),in:RoundedRectangle(cornerRadius:16));SecureField(language.text("Password","Mot de passe"),text:$password).textContentType(.password).padding().background(.secondary.opacity(0.10),in:RoundedRectangle(cornerRadius:16));HStack{Spacer();NavigationLink{ForgotPasswordView(auth:auth,language:language,email:email)}label:{Text(language.text("Forgot password?","Mot de passe oublié ?")).font(.subheadline.weight(.semibold)).foregroundStyle(.blue)}};if let error=auth.errorMessage{Text(authError(error)).font(.footnote).foregroundStyle(.red).multilineTextAlignment(.center)};Button{signingIn=true;Task{await auth.signIn(email:email.trimmingCharacters(in:.whitespacesAndNewlines),password:password);signingIn=false}}label:{Group{if signingIn{ProgressView().tint(.white)}else{Text(language.text("Sign in","Se connecter")).fontWeight(.semibold)}}.frame(maxWidth:.infinity).frame(height:54)}.buttonStyle(.borderedProminent).disabled(signingIn||email.isEmpty||password.isEmpty);HStack(spacing:5){Text(language.text("New to Libérons?","Nouveau sur Libérons ?")).foregroundStyle(.secondary);NavigationLink{SignUpView(auth:auth,language:language)}label:{Text(language.text("Create account","Créer un compte")).fontWeight(.semibold).foregroundStyle(.blue)}}.font(.subheadline);Spacer()}.padding(24).frame(maxWidth:.infinity,maxHeight:.infinity).background(LiberonsTheme.canvas.ignoresSafeArea()) } }
}

private struct MainAppView: View {
    @ObservedObject var auth:AuthStore; @ObservedObject var language:LanguageStore
    @StateObject private var analyzer=PhotoLibraryAnalyzer(); @StateObject private var preferences=BackupPreferences(); @StateObject private var backup=BackupEngine(); @StateObject private var cloud=CloudStorageSummary()
    var body: some View { TabView { DashboardView(analyzer:analyzer,cloud:cloud,language:language).tabItem{Label(language.text("Home","Accueil"),systemImage:"house.fill")}; BackupView(analyzer:analyzer,preferences:preferences,backup:backup,language:language).tabItem{Label(language.text("Backup","Sauvegarde"),systemImage:"icloud.and.arrow.up.fill")}; ProtectedLibraryView(language:language).tabItem{Label(language.text("Library","Bibliothèque"),systemImage:"photo.on.rectangle.angled")}; AccountView(auth:auth,cloud:cloud,language:language).tabItem{Label(language.text("Account","Compte"),systemImage:"person.crop.circle.fill")} }.task{async let a:Void=analyzer.refreshIfNeeded();async let b:Void=cloud.refresh();_=await(a,b)} }
}

private struct DashboardView: View {
    @ObservedObject var analyzer:PhotoLibraryAnalyzer; @ObservedObject var cloud:CloudStorageSummary; @ObservedObject var language:LanguageStore
    @State private var refreshing=false
    private var total:Int{analyzer.photoCount+analyzer.videoCount}; private var percent:Int{total==0 ? 0:min(100,Int(Double(cloud.protectedCount)/Double(total)*100))}; private var effectiveQuota:Int64{cloud.quotaBytes>0 ? cloud.quotaBytes:2_000_000_000}
    private var billedPlanDisplay:String{cloud.billedPlanQuotaBytes<=2_050_000_000 ? language.text("Free · 2 GB","Gratuit · 2 Go"):bytes(cloud.billedPlanQuotaBytes)}
    private var giftedDisplay:String{"+\(bytes(cloud.grantedBonusBytes))"}
    var body: some View { NavigationStack{ScrollView{VStack(alignment:.leading,spacing:16){Text("Libérons").font(.system(size:38,weight:.bold,design:.rounded));Text(language.text("Your memories, without the storage stress.","Vos souvenirs, sans le stress du stockage.")).foregroundStyle(.secondary);VStack(alignment:.leading,spacing:16){Label(language.text("Your photo library","Votre photothèque"),systemImage:"photo.stack.fill").font(.headline);Text(analyzer.formattedSize).font(.system(size:48,weight:.bold,design:.rounded));Text(language.text("across \(total.formatted()) photos and videos","répartis sur \(total.formatted()) photos et vidéos")).foregroundStyle(.secondary);HStack(spacing:10){Metric(icon:"photo.fill",value:analyzer.photoCount.formatted(),label:"Photos",tint:.blue);Metric(icon:"video.fill",value:analyzer.videoCount.formatted(),label:language.text("Videos","Vidéos"),tint:.purple)}}.card();VStack(alignment:.leading,spacing:14){HStack{Label("Libérons",systemImage:"icloud.fill").font(.headline).foregroundStyle(.blue);Spacer();Text(bytes(cloud.protectedBytes)).fontWeight(.bold)};ProgressView(value:min(1,Double(cloud.protectedBytes+cloud.pendingBytes)/Double(effectiveQuota))).tint(.blue);HStack(spacing:10){Metric(icon:"checkmark.shield.fill",value:cloud.protectedCount.formatted(),label:language.text("Protected","Protégés"),tint:.green);Metric(icon:"creditcard.fill",value:billedPlanDisplay,label:language.text("Current plan","Forfait actuel"),tint:.blue)};if cloud.hasGrantedBonus{HStack(spacing:10){Image(systemName:"gift.fill").foregroundStyle(.green);VStack(alignment:.leading,spacing:2){Text(language.text("Offered by Libérons","Offert par Libérons")).font(.caption).foregroundStyle(.secondary);Text(giftedDisplay).font(.headline)};Spacer();VStack(alignment:.trailing,spacing:2){Text(language.text("Total capacity","Capacité totale")).font(.caption).foregroundStyle(.secondary);Text(bytes(effectiveQuota)).font(.headline)}}.padding(14).background(Color.green.opacity(0.08),in:RoundedRectangle(cornerRadius:18,style:.continuous))}}.card();HStack(spacing:10){Metric(icon:"shield.checkered",value:"\(percent)%",label:language.text("Library protected","Photothèque protégée"),tint:.green);DeviceMediaMetric(value:total.formatted(),label:language.text("On this iPhone","Sur cet iPhone"))};VStack(alignment:.leading,spacing:12){Text(language.text("Protection status","État de protection")).font(.headline);Label(cloud.protectedCount>0 ? language.text("Libérons protection active","Protection Libérons active"):language.text("Ready to protect","Prêt à protéger"),systemImage:cloud.protectedCount>0 ? "checkmark.circle.fill":"shield.fill").foregroundStyle(cloud.protectedCount>0 ? .green:.orange);Divider();Label(language.text("Originals stay on this iPhone until you choose to free space.","Les originaux restent sur cet iPhone jusqu’à ce que vous choisissiez de libérer de l’espace."),systemImage:"iphone").font(.subheadline).foregroundStyle(.secondary)}.card();Button{guard !refreshing else{return};refreshing=true;Task{async let a:Void=analyzer.refreshDashboardFast();async let b:Void=cloud.refresh();_=await(a,b);refreshing=false}}label:{HStack{if refreshing{ProgressView().controlSize(.small)};Label(language.text(refreshing ? "Refreshing…":"Refresh dashboard",refreshing ? "Actualisation…":"Actualiser le tableau de bord"),systemImage:"arrow.clockwise")}.frame(maxWidth:.infinity).frame(height:42)}.buttonStyle(.borderedProminent).disabled(refreshing||cloud.isLoading)}.padding(20).padding(.bottom,100)}.background(LiberonsTheme.canvas).toolbar(.hidden,for:.navigationBar)} }
    private func bytes(_ n:Int64)->String{n==0 ? language.text("0 KB","0 Ko"):ByteCountFormatter.string(fromByteCount:n,countStyle:.file)}
}

private struct BackupView: View {
    @ObservedObject var analyzer:PhotoLibraryAnalyzer;@ObservedObject var preferences:BackupPreferences;@ObservedObject var backup:BackupEngine;@ObservedObject var language:LanguageStore
    private var total:Int{analyzer.photoCount+analyzer.videoCount};private var protectedBytes:Int64{Int64(Double(analyzer.estimatedBytes)*Double(preferences.backupPercent)/100)};private var removableBytes:Int64{Int64(Double(protectedBytes)*Double(preferences.removalPercent)/100)}
