e).foregroundStyle(.green);Text(ByteCountFormatter.string(fromByteCount:removableBytes,countStyle:.file)).font(.system(size:40,weight:.bold,design:.rounded));PercentPicker(selection:$preferences.removalPercent);Text(language.text("Only verified protected originals are eligible.","Seuls les originaux protégés et vérifiés sont éligibles.")).font(.caption).foregroundStyle(.secondary)}.card();FreeSpaceView(preferences:preferences,language:language,backup:backup)}.padding(20).padding(.bottom,100)}.background(LiberonsTheme.canvas).toolbar(.hidden,for:.navigationBar)}}
}

