Task.sleep(for:.seconds(3));await MainActor.run{withAnimation(.easeOut(duration:0.2)){cacheMessage=nil}}}}label:{HStack{if clearingCache{ProgressView().controlSize(.small)};Label(language.text("Clear cache","Vider le cache"),systemImage:"trash")}.frame(maxWidth:.infinity).frame(height:44)}.buttonStyle(.bordered);if let cacheMessage{Label(cacheMessage,systemImage:"checkmark.circle.fill").font(.caption.weight(.semibold)).foregroundStyle(.green).transition(.opacity)}}.card();Button{showingLanguagePicker=true}label:{HStack{Label(language.text("Language","Langue"),systemImage:"globe");Spacer();Text(language.language.title).foregroundStyle(.secondary);Image(systemName:"chevron.right").foregroundStyle(.tertiary)}}.buttonStyle(.plain).card();NavigationLink{AccountSecurityView(auth:auth,language:language)}label:{HStack{Label(language.text("Security","Sécurité"),systemImage:"lock.shield.fill");Spacer();Image(systemName:"chevron.right").foregroundStyle(.tertiary)}}.buttonStyle(.plain).card();NavigationLink{AppSettingsView(language:language)}label:{HStack{Label(language.text("Settings","Réglages"),systemImage:"gearshape.fill");Spacer();Image(systemName:"chevron.right").foregroundStyle(.tertiary)}}.buttonStyle(.plain).card();Button(role:.destructive){Task{await auth.signOut()}}label:{Label(language.text("Sign out","Se déconnecter"),systemImage:"rectangle.portrait.and.arrow.right").frame(maxWidth:.infinity).frame(height:44)}.buttonStyle(.bordered).card()}.padding(20).padding(.bottom,100)}.background(LiberonsTheme.canvas).toolbar(.hidden,for:.navigationBar)}.sheet(isPresented:$showingLanguagePicker){NavigationStack{List(LanguageStore.Language.allCases){item in Button{language.language=item;showingLanguagePicker=false}label:{HStack{Text(item.title).foregroundStyle(.primary);Spacer();if language.language==item{Image(systemName:"checkmark").foregroundStyle(.blue)}}}}.navigationTitle(language.text("Language","Langue")).navigationBarTitleDisplayMode(.inline).toolbar{ToolbarItem(placement:.cancellationAction){Button(language.text("Close","Fermer")){showingLanguagePicker=false}}}}.presentationDetents([.medium])}}.task{localBytes=LocalStorageGuard.reclaimableBytes()}}
