private struct StoragePlanView: View {
    @ObservedObject var cloud:CloudStorageSummary; @ObservedObject var language:LanguageStore
    private let plans:[(String,Int64,String)]=[("50 GB",50_000_000_000,"$4.99"),("100 GB",100_000_000_000,"$7.99"),("250 GB",250_000_000_000,"$12.99"),("500 GB",500_000_000_000,"$17.99"),("1 TB",1_000_000_000_000,"$24.99")]
    private var effectiveQuota:Int64{cloud.quotaBytes>0 ? cloud.quotaBytes:2_000_000_000}
    private var billedQuota:Int64{cloud.billedPlanQuotaBytes>0 ? cloud.billedPlanQuotaBytes:2_000_000_000}
    private var billedName:String{billedQuota<=2_050_000_000 ? language.text("Free · 2 GB","Gratuit · 2 Go"):ByteCountFormatter.string(fromByteCount:billedQuota,countStyle:.file)}
    private var billedPrice:String{guard let cents=cloud.billedPlanPriceCents,cents>0 else{return language.text("Free","Gratuit")};let amount=Double(cents)/100;return String(format:"$%.2f %@ / %@",amount,cloud.billedPlanCurrency.uppercased(),language.text("month","mois"))}
    var body:some View{ScrollView{VStack(alignment:.leading,spacing:16){VStack(alignment:.leading,spacing:10){Label(language.text("Total Libérons capacity","Capacité totale Libérons"),systemImage:"externaldrive.fill").font(.headline).foregroundStyle(.blue);Text(ByteCountFormatter.string(fromByteCount:effectiveQuota,countStyle:.file)).font(.system(size:42,weight:.bold,design:.rounded));Text(language.text("This is the total capacity currently available on your account.","C’est la capacité totale actuellement disponible sur votre compte.")).font(.subheadline).foregroundStyle(.secondary)}.card();if cloud.hasGrantedBonus{VStack(alignment:.leading,spacing:10){Label(language.text("Extra space offered by Libérons","Espace supplémentaire offert par Libérons"),systemImage:"gift.fill").font(.headline).foregroundStyle(.green);Text("+\(ByteCountFormatter.string(fromByteCount:cloud.grantedBonusBytes,countStyle:.file))").font(.system(size:34,weight:.bold,design:.rounded));Text(language.text("This extra capacity is offered by Libérons. It does not change the plan you are billed for.","Cette capacité supplémentaire est offerte par Libérons. Elle ne modifie pas le forfait qui vous est facturé.")).font(.subheadline).foregroundStyle(.secondary)}.card()};VStack(alignment:.leading,spacing:10){Label(language.text("Your billed plan","Votre forfait facturé"),systemImage:"creditcard.fill").font(.headline).foregroundStyle(.blue);Text(billedName).font(.system(size:32,weight:.bold,design:.rounded));HStack{Text(billedPrice).font(.headline);Spacer();Label(language.text("Current","Actuel"),systemImage:"checkmark.circle.fill").font(.subheadline.weight(.semibold)).foregroundStyle(.green)};Text(language.text("Only this plan is billed. Any additional capacity shown above is an extra benefit offered by Libérons.","Seul ce forfait est facturé. Toute capacité supplémentaire affichée ci-dessus est un avantage offert par Libérons.")).font(.caption).foregroundStyle(.secondary)}.card();VStack(alignment:.leading,spacing:12){Text(language.text("Available plans","Forfaits disponibles")).font(.headline);ForEach(plans,id:\.1){plan in let isCurrent=abs(plan.1-billedQuota)<2_000_000_000;HStack{VStack(alignment:.leading,spacing:3){Text(plan.0).font(.headline);Text("\(plan.2) USD / \(language.text("month","mois"))").font(.caption).foregroundStyle(.secondary)};Spacer();if isCurrent{Text(language.text("Current","Actuel")).font(.caption.bold()).foregroundStyle(.green)}else{Image(systemName:"chevron.right").foregroundStyle(.tertiary)}}.padding(.vertical,6)}}.card();VStack(alignment:.leading,spacing:8){Label(language.text("Plan management","Gestion du forfait"),systemImage:"creditcard.fill").font(.headline);Text(language.text("Changing a paid plan will be connected to secure billing. Extra capacity granted by Libérons is not billed as a higher plan.","Le changement d’un forfait payant sera relié à la facturation sécurisée. La capacité supplémentaire accordée par Libérons n’est pas facturée comme un forfait supérieur.")).font(.subheadline).foregroundStyle(.secondary)}.card()}.padding(20)}.background(LiberonsTheme.canvas).navigationTitle(language.text("Libérons plan","Forfait Libérons")).navigationBarTitleDisplayMode(.inline)}
}

private struct Metric:View{let icon:String;let value:String;let label:String;let tint:Color;var body:some View{VStack(alignment:.leading,spacing:7){Image(systemName:icon).foregroundStyle(tint);Text(value).font(.title2.bold());Text(label).font(.caption).foregroundStyle(.secondary)}.frame(maxWidth:.infinity,alignment:.leading).padding(16).background(.background,in:RoundedRectangle(cornerRadius:20))}}
private struct DeviceMediaMetric:View{let value:String;let label:String;var body:some View{VStack(alignment:.leading,spacing:7){HStack(spacing:4){Image(systemName:"photo.fill").foregroundStyle(.orange);Image(systemName:"video.fill").foregroundStyle(.purple)};Text(value).font(.title2.bold());Text(label).font(.caption).foregroundStyle(.secondary)}.frame(maxWidth:.infinity,alignment:.leading).padding(16).background(.background,in:RoundedRectangle(cornerRadius:20))}}
private struct PercentPicker:View{@Binding var selection:Int;var body:some View{HStack(spacing:8){ForEach([25,50,75,100],id:\.self){v in Button("\(v)%"){selection=v}.buttonStyle(.borderedProminent).tint(selection==v ? .blue:.gray)}}}}
private extension View{func card()->some View{self.padding(18).background(LiberonsTheme.card,in:RoundedRectangle(cornerRadius:28,style:.continuous)).overlay(RoundedRectangle(cornerRadius:28,style:.continuous).stroke(Color.primary.opacity(0.035),lineWidth:1))}}
